    // catalog sub-sections
    'docs.cat.heading': 'Catalog API',
    'docs.cat.intro': 'Read-only endpoints to navigate the supplier-direct catalog: categories, products, variants, technical specifications, taxonomic attributes, tags, images, price tiers, and shipping coverage.',
    'docs.cat.categories.title': 'Categories',
    'docs.cat.categories.intro': 'Fourteen top-level categories drive the storefront. Each one can host children (sub-categories). Query them flat, as a tree, by id or by slug.',
    'docs.cat.categories.ep_flat': 'List top-level categories (flat).',
    'docs.cat.categories.ep_tree': 'List the full category tree with children expanded.',
    'docs.cat.categories.ep_detail': 'Fetch a single category by id OR slug, including direct product count.',
    'docs.cat.categories.ep_children': 'List immediate children of a category.',
    'docs.cat.categories.ep_breadcrumb': 'Ancestor chain from the root down to the requested category (useful for breadcrumb UIs).',
    'docs.cat.categories.ep_products': 'Paginated products inside a category (uses the same filters as /products).',
    'docs.cat.products.title': 'Products',
    'docs.cat.products.intro': 'Paginated list with rich filters, then six ways to read a single product or its related data.',
    'docs.cat.products.ep_list': 'Paginated product list. All filters combine with AND.',
    'docs.cat.products.ep_by_slug': 'Read a product by its storefront slug (the URL-friendly identifier).',
    'docs.cat.products.ep_by_id': 'Read a product by its internal UUID.',
    'docs.cat.products.ep_by_external': 'Look up by the supplier-side offer id (e.g. OFFER-01023).',
    'docs.cat.products.ep_bestsellers': 'Highest-trending products globally or scoped by category.',
    'docs.cat.products.ep_trending': 'Alias for bestsellers with default ordering.',
    'docs.cat.products.ep_newest': 'Most recently ingested products.',
    'docs.cat.products.ep_related': 'Up to N products in the same category, ordered by trend score.',
    'docs.cat.products.ep_specs': 'Technical specifications (Brand, Material, Weight, …) translated to the requested locale.',
    'docs.cat.products.ep_attrs': 'Taxonomic attributes (brand, season, age_group, origin, category).',
    'docs.cat.products.ep_tags': 'Free-form tags attached to the product.',
    'docs.cat.products.ep_images': 'Full image gallery (sourceUrl + CDN url + role).',
    'docs.cat.products.ep_tiers': 'Quantity-break price tiers (MOQ pricing).',
    'docs.cat.products.ep_suggest': 'Autocomplete suggestions while the user types in the search box.',
    'docs.cat.variants.title': 'Variants',
    'docs.cat.variants.intro': 'Each product can have multiple SKUs distinguished by options (color/size/plug). Variants carry their own price, stock and image.',
    'docs.cat.variants.ep_list': 'All active variants of a product.',
    'docs.cat.variants.ep_by_id': 'Single variant by global UUID.',
    'docs.cat.variants.ep_by_sku': 'Find a variant by its internal SKU or by the supplier external id.',
    'docs.cat.variants.ep_match': 'Filter variants by option map — pass {color: "red", size: "M"} to get only matches.',
    'docs.cat.attrs.title': 'Specifications & attributes',
    'docs.cat.attrs.intro': 'Two related concepts: free-form **specifications** (translated key/value text shown on the product page) and discrete **attributes** (used for faceted search across the catalog).',
    'docs.cat.attrs.ep_keys': 'List every attribute key present in the catalog with its usage count.',
